CREATE UNIQUE INDEX IF NOT EXISTS chip_ledger_chain_seq_key ON public.chip_ledger USING btree (chain_seq);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_club_created_desc ON public.chip_ledger USING btree (club_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_club_from_created ON public.chip_ledger USING btree (club_id, from_entity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_club_to_created ON public.chip_ledger USING btree (club_id, to_entity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_created_at ON public.chip_ledger USING btree (created_at);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_from_entity_created ON public.chip_ledger USING btree (from_entity_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_overlay_by_tournament ON public.chip_ledger USING btree (tournament_id) INCLUDE (amount) WHERE ((tournament_id IS NOT NULL) AND (category = 'overlay'::text) AND (to_type = 'prize_liability'::text));
CREATE INDEX IF NOT EXISTS idx_chip_ledger_performed_by ON public.chip_ledger USING btree (performed_by);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_promo_from ON public.chip_ledger USING btree (from_entity_id, created_at DESC) WHERE (from_type = 'promo_wallet'::text);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_promo_to ON public.chip_ledger USING btree (to_entity_id, created_at DESC) WHERE (to_type = 'promo_wallet'::text);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_rebuy_probe ON public.chip_ledger USING btree (from_entity_id, tournament_id, created_at) WHERE ((category = 'rebuy'::text) AND (from_type = 'player_wallet'::text) AND (to_type = 'prize_liability'::text) AND (status = 'posted'::text));
CREATE INDEX IF NOT EXISTS idx_chip_ledger_to_entity ON public.chip_ledger USING btree (to_entity_id);
CREATE INDEX IF NOT EXISTS idx_chip_ledger_to_entity_created ON public.chip_ledger USING btree (to_entity_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_chip_ledger_settlement ON public.chip_ledger USING btree (settlement_id) WHERE (settlement_id IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ux_chip_ledger_idempotency_key ON public.chip_ledger USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL);
